/**
 * Censo de las 392 firmas visuales de botón que existen hoy en Vibra.
 *
 * GENERADO por un barrido del repositorio, no escrito a mano. Cada entrada trae
 * el estilo REAL sacado del archivo donde vive, cuántos botones lo comparten y
 * a qué pieza del sistema nuevo se propone mandarlo.
 *
 * Se usa solo en /simulador-botones para comparar el antes y el después. No lo
 * importa nada del producto.
 */

export type FirmaActual = {
  borderRadius?: string;
  padding?: string;
  background?: string;
  border?: string;
  color?: string;
  fontSize?: string;
  fontWeight?: string;
  width?: string;
  height?: string;
};

export type Destino =
  | "primary" | "brand" | "gradient" | "secondary" | "ghost" | "ghost-borde"
  | "danger" | "success" | "pill"
  | "icon" | "icon-solid" | "close"
  | "text-brand" | "text-mute"
  | "fuera" | "dinamico" | "otro";

/** El SVG real del botón, ya convertido de JSX a marcado de navegador. */
export type IconoSvg = {
  viewBox: string;
  relleno: string;
  trazo: string;
  grosor: string;
  /** Solo formas (path, circle, rect…) con atributos literales. */
  html: string;
};

export type EntradaCenso = {
  n: number;
  firma: FirmaActual;
  total: number;
  destino: Destino;
  tamano: "sm" | "md" | "lg";
  archivos: string[];
  /** Texto real del botón, con las claves de next-intl ya resueltas al español. */
  etiqueta?: string;
  /** Icono real, cuando el botón lleva un <svg> escrito ahí mismo. */
  svg?: IconoSvg;
  /** Nombre del componente de icono, cuando el icono viene de uno. */
  componente?: string;
};

